    end
    assign rc = frac[RW+K-1 -: K] >= 212;
    reg [WROM-1:0] rom_q;
    reg [RW-1:0]   w_r;
    reg            v_r;
    always @(posedge clk) begin
        if (rst) v_r <= 1'b0;
        else     v_r <= in_valid;
        rom_q <= rom[frac[RW+K-1 -: K]];
        w_r   <= frac[RW-1:0];
    end
    wire [W0-1:0] c0 = {1'b1, rom_q[W0-2:0]};
    wire [W1-1:0] c1 = rom_q[60 +: W1];
    wire [W2-1:0] c2 = rom_q[111 +: W2];
    wire [W3-1:0] c3 = rom_q[152 +: W3];
    wire [W4-1:0] c4 = rom_q[184 +: W4];
    wire [W5-1:0] c5 = rom_q[207 +: W5];

    // c0 - c1*w, the wide product, held if the chain takes longer.
    wire v_p;
    wire [W1+T1-1:0] p1;
    _zkf_pmul #(
        .WA(W1), .WB(T1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT)
    ) u_p1 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c1), .b(w_r[RW-1 -: T1]),
        .out_valid(v_p), .sb_out(), .p(p1)
    );
    wire [W0-1:0] c0_d;
    zkf_pipe #(.W(W0), .N(NK)) u_c0 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c0), .out_valid(), .out(c0_d)
    );
    wire [W1-1:0] p1_d;
    zkf_pipe #(.W(W1), .N(NK - 1 - STAGE_PRODUCT)) u_p1_d (
        .clk(clk), .rst(rst), .in_valid(v_p), .in(p1[W1+T1-1:T1]), .out_valid(out_valid), .out(p1_d)
    );

    wire [TS-1:0] ws = w_r[RW-1 -: TS];
    wire v_s;  // the valid of the square
    // The pairs c[2i] - c[2i+1]*w above the wide one, each held for its turn.
    wire [W3+T3-1:0] p3;
    _zkf_pmul #(
        .WA(W3), .WB(T3), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_ODD), .STAGE_OUTPUT(0)
    ) u_p3 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c3), .b(w_r[RW-1 -: T3]),
        .out_valid(), .sb_out(), .p(p3)
    );
    wire [W2-1:0] c2_d;
    zkf_pipe #(.W(W2), .N(STAGE_PRODUCT_ODD)) u_c2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c2), .out_valid(), .out(c2_d)
    );
    wire [W2-1:0] pair1_0 = c2_d - p3[W3+T3-1:T3];
    wire [W2-1:0] pair1;
    zkf_pipe #(.W(W2), .N(NF + 1 * (1 + STAGE_PRODUCT_CHAIN) - STAGE_PRODUCT_ODD)) u_pair1 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(pair1_0), .out_valid(), .out(pair1)
    );
    wire [W5+T5-1:0] p5;
    _zkf_pmul #(
        .WA(W5), .WB(T5), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_ODD), .STAGE_OUTPUT(0)
    ) u_p5 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c5), .b(w_r[RW-1 -: T5]),
        .out_valid(), .sb_out(), .p(p5)
    );
    wire [W4-1:0] c4_d;
    zkf_pipe #(.W(W4), .N(STAGE_PRODUCT_ODD)) u_c4 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c4), .out_valid(), .out(c4_d)
    );
    wire [W4-1:0] pair2_0 = c4_d - p5[W5+T5-1:T5];
    wire [W4-1:0] pair2;
    zkf_pipe #(.W(W4), .N(NF - STAGE_PRODUCT_ODD)) u_pair2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(pair2_0), .out_valid(), .out(pair2)
    );
    // chain = w**2 * (pair1 + w**2 * pair2), each product registered as the bits the next sum takes.
    wire [TS+TS-1:0] sq;
    _zkf_pmul #(
        .WA(TS), .WB(TS), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(SQP), .STAGE_OUTPUT(SQO)
    ) u_sq (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(ws), .b(ws),
        .out_valid(v_s), .sb_out(), .p(sq)
    );
    wire [Q0-1:0] sq_0;
    wire v_0;
    zkf_pipe #(.W(Q0), .N(NF - STAGE_PRODUCT_SQUARE)) u_sq_0 (
        .clk(clk), .rst(rst), .in_valid(v_s), .in(sq[2*TS-1 -: Q0]), .out_valid(v_0), .out(sq_0)
    );
    wire v_p4, v_1;
    wire [W4+Q1-1:0] p4;
    _zkf_pmul #(
        .WA(W4), .WB(Q1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p4 (
        .clk(clk), .rst(rst), .in_valid(v_0), .sb_in(1'b0), .a(pair2), .b(sq_0[Q0-1 -: Q1]),
        .out_valid(v_p4), .sb_out(), .p(p4)
    );
    wire [W4-1:0] p4_r;
    zkf_pipe #(.W(W4), .N(1)) u_p4_r (
        .clk(clk), .rst(rst), .in_valid(v_p4), .in(p4[W4+Q1-1:Q1]), .out_valid(v_1), .out(p4_r)
    );
    wire [W2-1:0] chain1 = pair1 + p4_r;
    wire [Q0-1:0] sq_1;
    zkf_pipe #(.W(Q0), .N(1 + STAGE_PRODUCT_CHAIN)) u_sq_1 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(sq_0), .out_valid(), .out(sq_1)
    );
    wire [W2+Q0-1:0] p2;
    _zkf_pmul #(
        .WA(W2), .WB(Q0), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p2 (
        .clk(clk), .rst(rst), .in_valid(v_1), .sb_in(1'b0), .a(chain1), .b(sq_1),
        .out_valid(), .sb_out(), .p(p2)
    );
    wire [W2-1:0] p2_d;
    zkf_pipe #(.W(W2), .N(NK - NL)) u_p2_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(p2[W2+Q0-1:Q0]), .out_valid(), .out(p2_d)
    );
    reg  [W2-1:0] chain;
    always @(posedge clk) chain <= p2_d;
    assign c = c0_d - p1_d + chain;
endmodule

